<?php
require_once __DIR__.'/includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/config/database.php';if(!isset($_SESSION['cart'])||!is_array($_SESSION['cart']))$_SESSION['cart']=[];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['product_id']??null,FILTER_VALIDATE_INT);if($action==='clear'){$_SESSION['cart']=[];$notice='Себет тазартылды.';}elseif(in_array($action,['add','update','remove'],true)&&$id){if($action==='remove'){unset($_SESSION['cart'][$id]);$notice='Өнім себеттен алынды.';}else{$q=$pdo->prepare('SELECT id,stock FROM products WHERE id=:id');$q->execute(['id'=>$id]);$product=$q->fetch();if(!$product){$notice='Өнім табылмады.';}elseif($action==='add'){$qty=max(1,(int)($_POST['quantity']??1));$existing=(int)($_SESSION['cart'][$id]??0);$_SESSION['cart'][$id]=min((int)$product['stock'],$existing+$qty);$notice='Өнім себетке қосылды.';}else{$qty=(int)($_POST['quantity']??1);if($qty<1)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min((int)$product['stock'],$qty);$notice='Себет жаңартылды.';}}}}
$ids=array_keys($_SESSION['cart']);$items=[];$total=0;if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=$pdo->prepare("SELECT id,name,category,price,image,stock FROM products WHERE id IN ($marks)");$stmt->execute($ids);foreach($stmt->fetchAll() as $p){$qty=min((int)($_SESSION['cart'][$p['id']]??0),(int)$p['stock']);if($qty<1){unset($_SESSION['cart'][$p['id']]);continue;}$p['quantity']=$qty;$p['subtotal']=$qty*(float)$p['price'];$total+=$p['subtotal'];$items[]=$p;}}
$pageTitle='Себет — Apple Store';require __DIR__.'/includes/header.php';
?><section class="page-intro compact-intro"><p class="eyebrow">СЕБЕТ</p><h1>Таңдауың дайын.</h1></section><section class="cart-wrap section-pad"><?php if($notice): ?><div class="alert alert-success"><?= e($notice) ?></div><?php endif; ?><?php if(!$items): ?><div class="empty-state"><span class="empty-icon">⌑</span><h2>Себетіңіз әзірге бос.</h2><p>Каталогтан өзіңізге ұнаған өнімді таңдаңыз.</p><a class="button button-dark" href="products.php">Өнімдерді көру</a></div><?php else: ?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $item): ?><article class="cart-item"><a class="cart-thumb" href="product.php?id=<?= (int)$item['id'] ?>"><?= product_image($item) ?><span class="image-placeholder"></span></a><div class="cart-item-copy"><p class="eyebrow"><?= e($item['category']) ?></p><h2><a href="product.php?id=<?= (int)$item['id'] ?>"><?= e($item['name']) ?></a></h2><strong><?= money($item['price']) ?></strong></div><form method="post" class="cart-qty"><?= csrf_field() ?><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><label class="sr-only" for="qty-<?= (int)$item['id'] ?>">Саны</label><input id="qty-<?= (int)$item['id'] ?>" type="number" name="quantity" min="1" max="<?= (int)$item['stock'] ?>" value="<?= $item['quantity'] ?>"><button class="text-button" type="submit">Жаңарту</button></form><div class="cart-subtotal"><?= money($item['subtotal']) ?></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button class="remove-button" aria-label="Өнімді жою">×</button></form></article><?php endforeach; ?></div><aside class="cart-summary"><h2>Тапсырыс</h2><p><span>Барлығы</span><strong><?= money($total) ?></strong></p><p class="fine-print">Бұл оқу жобасында төлем жүйесі қосылмаған.</p><a class="button button-dark button-full" href="products.php">Сатып алуды жалғастыру</a><form method="post" class="clear-cart-form"><?= csrf_field() ?><input type="hidden" name="action" value="clear"><button class="text-link" type="submit">Себетті тазалау</button></form></aside></div><?php endif; ?></section><?php require __DIR__.'/includes/footer.php'; ?>
